import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createReport } from "../handlers/createReport";
import type { ApiError } from "../runtime/client";
import type { CreateReportRequest } from "../types/CreateReportRequest";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof createReport>>;
type Vars = { spacePk: SpacePartition; req: CreateReportRequest };

export function useCreateReport(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createReport(vars.spacePk, vars.req),
    ...options,
  });
}
